#!/usr/bin/env python
# ── GENERATED by matsci-kb-kit build/build_kit.py — DO NOT EDIT (真源见 kit.yaml) ──
r"""规范建议 1 的回填器：为 concept / topic 页计算并写入 `evidence_base`。

背景（根因一）
--------------
`source_reliability` 在 sources 页是 362/362，在 concepts 页只有 8/117。
CLAUDE.md 的批判性纪律**全部为 source 型页设计**，从未定义综合页如何承载
「这条结论的来源可靠到什么程度」⇒ 限定词在 `source → concept` 这一跳
**必然丢失，因为综合页没有地方记**。

字段设计（见 CLAUDE.md §页面规范）
----------------------------------
    evidence_base: strong | mixed | single-source | secondhand

取值规则（**可机械判定，不掺主观**）：
  · 先看该页 `sources:` 引用的各 source 页的 `source_reliability` 与 `si_status`
  · `secondhand`  = 二手源占比 > 0 且 ≥ 1/3
  · `single-source` = 有效一手源 ≤ 1
  · `mixed`       = 有效一手源 ≥ 2 且二手源占比 < 1/3
  · `strong`      = 有效一手源 ≥ 5 **且** 二手源占比 = 0
                    **且** 其中至少 2 个 source 页的 raw 是**出版方全文 HTML**
                    （即 raw 路径含 `clippings` 之外的发布源，或来源页标注了同行评审）

  ⚠️ 判据故意保守：**宁可给 mixed，不给 strong**。`strong` 是强断言，
     误标 strong 会让下游把单源结论读成领域共识——正是本任务要治的病。

判定输入（只读，不写 raw）：
  1. concept/topic 页 frontmatter 的 `sources:`
  2. 被引 source 页的 `source_reliability` 文本（含「预印本 / 公众号 / 同行评审」等词）
  3. 被引 source 页的 `si_status`

用法：
  python tools/qc_evidence_base.py            # 干跑，打印每个页面的判定与依据
  python tools/qc_evidence_base.py --apply    # 就地写入 evidence_base
  python tools/qc_evidence_base.py --selftest # 用夹具反算判定函数
"""
import sys
import os
import re
import glob
from collections import Counter

# 🔴 必须**守卫**且带 errors 兜底。2026-10-10 实测后果：
#   `kb_lint.py --deep --json` 会把 sys.stdout 换成 io.StringIO，而 StringIO
#   **没有 reconfigure** ⇒ 本模块在 import 期抛 AttributeError；
#   调用方 `kb_lint_deep` 的 `try: import qc_evidence_base / except Exception: return []`
#   把异常吞掉 ⇒ **B3（evidence_base ↔ sources 重算）在 --json 模式下整轮静默禁用**。
#   它是本库唯一会自己校验「证据承重」的检查，静默禁用等于该维度长期无人管。
try:                                                           # noqa: SIM105
    sys.stdout.reconfigure(encoding="utf-8", errors="replace")
except Exception:                                              # noqa: BLE001
    pass
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import (read_text, split_frontmatter, parse_frontmatter,  # noqa: E402
                    join_frontmatter)


def match_frontmatter(text):
    """用与 kb_lib 完全相同的解析器判断 frontmatter 是否可解析。

    **不要**在这里另写正则：初版事故正是因为校验正则比 kb_lib 宽松，
    导致「校验通过、实际已坏」。校验必须复用被校验系统的解析器。
    """
    return bool(split_frontmatter(text)[0])

# 「二手源」指纹：公众号 / 解读 / 剪藏网页
SECONDHAND_PAT = re.compile(
    r"公众号|微信|mp\.weixin|二次解读|二手|媒体|新闻报道|新闻稿", re.I)
# 预印本指纹
PREPRINT_PAT = re.compile(r"预印本|arXiv|bioRxiv|chemRxiv", re.I)
# 一手同行评审指纹
PEER_PAT = re.compile(r"同行评审|peer.?review", re.I)
# 否定式：句子里出现这些时，PEER_PAT 的命中是**否定**（"未经同行评审"），不算正向证据
PEER_NEG_PAT = re.compile(r"未(?:经)?\s*同行评审|非\s*同行评审|未经评审|not\s+peer.?review", re.I)


def _peer_hits(sr):
    """判断 source_reliability 是否含**肯定式**同行评审证据。

    ⚠️ 不能只 `PEER_PAT.search`：本库预印本页写的是「未经同行评审」，
    `同行评审` 四字照样命中 ⇒ 会把真预印本计入 peer（selftest 已抓到该回归）。
    做法：去掉所有否定式之后，再看是否仍有肯定命中。
    """
    stripped = PEER_NEG_PAT.sub("", sr)
    return bool(PEER_PAT.search(stripped))

VALID = ("strong", "mixed", "single-source", "secondhand")


def load_source_pages():
    """加载全部 source 页的 {页面名: (fm, body)}"""
    out = {}
    for f in glob.glob("wiki/sources/*.md"):
        t = read_text(f)
        a, b = split_frontmatter(t)
        out[os.path.basename(f)[:-3]] = (parse_frontmatter(a), b)
    return out


def _resolve_source_name(link):
    """从 sources: 条目取被引 source 页名"""
    t = str(link).replace("\\|", "|").split("|")[0].strip()
    t = t.strip('"').strip("'").strip()
    if t.startswith("[["):
        t = t[2:]
    if t.endswith("]]"):
        t = t[:-2]
    t = t.replace("\\", "").split("/")[-1]
    if t.endswith(".md"):
        t = t[:-3]
    return t


def classify(cited_fms):
    """核心判定函数（可被 --selftest 反算）。

    cited_fms: list of (fm_dict, body) —— 本页 `sources:` 实际命中的 source 页
    返回 (evidence_base, 依据字符串)

    ⚠️ 本函数是**纯函数**：不读盘、不看页面名，只依据传入的 fm。
       这样 selftest 才能用夹具反算，避免「改一行正则、静默改全库标签」。
    """
    if not cited_fms:
        return "single-source", "未解析到任何 source 页（sources: 字段可能为空或路径不匹配）"

    n_second = n_preprint = n_peer = 0
    details = []
    for fm, _body in cited_fms:
        sr = str(fm.get("source_reliability") or "")
        # ⚠️ 判定顺序即语义，**不可随意调换**（2026-09-25 实测踩坑）：
        # 本库大量**已发表**论文的 source_reliability 里同时出现「预印本」
        #   —— 因为原句在**否认**它是预印本（"非预印本"、"arXiv 版与正式版并行"）。
        # 首版把 PREPRINT 判在 PEER 之前 ⇒ 127 个 source 页被误判为预印本，
        # 进而使全部 concept 页都拿不到 `strong`（实测 strong = 0，是红灯不是结论）。
        # ⇒ 语义应为：**先认「同行评审」为正向证据；预印本只在无同行评审时才成立**。
        is_second = bool(SECONDHAND_PAT.search(sr))
        is_peer = _peer_hits(sr)
        is_pre = bool(PREPRINT_PAT.search(sr))
        if is_second:
            n_second += 1
            details.append("二手")
        elif is_peer:
            # 同行评审优先；若同时提到预印本，视为「已有正式版」，计入 peer
            n_peer += 1
            details.append("同行评审")
        elif is_pre:
            n_preprint += 1
            details.append("预印本")
        else:
            details.append("未标注")

    total = len(cited_fms)
    prim = total - n_second                      # 一手源数（含预印本）
    second_ratio = n_second / total

    # 判据序：secondhand → single-source → strong → mixed
    if second_ratio >= 1 / 3:
        return ("secondhand",
                f"二手源 {n_second}/{total}（占比 {second_ratio:.0%} ≥ 1/3）")
    if prim <= 1:
        return ("single-source", f"一手源仅 {prim}/{total}（≤1）")
    if prim >= 5 and n_second == 0 and n_preprint == 0 and n_peer >= 2:
        return ("strong",
                f"一手源 {prim}（≥5）、无二手无预印本、其中同行评审 {n_peer} 篇")
    return ("mixed",
            f"一手源 {prim}/{total}，二手占比 {second_ratio:.0%}，"
            f"同行评审 {n_peer}、预印本 {n_preprint}")


def evidence_for(page_path, src_pages):
    """取该 concept/topic 页的 sources: 命中的 source 页 fm 列表"""
    t = read_text(page_path)
    a, _b = split_frontmatter(t)
    fm = parse_frontmatter(a)
    srcs = fm.get("sources") or []
    if isinstance(srcs, str):
        srcs = [srcs]
    hits = []
    for s in srcs:
        nm = _resolve_source_name(s)
        if nm in src_pages:
            hits.append(src_pages[nm])
    return fm, hits


def write_field(page_path, value):
    """在 frontmatter 中写入/更新 evidence_base（幂等）

    ⚠️ 2026-09-25 事故：初版写成 `"---\\n" + a2.strip("\\n") + "\\n---" + b`，
    **闭合 `---` 后没补换行**，产出 `...mixed\\n---# 标题`。
    后果：`kb_lib._FM_RE` 要求 `---` 后跟 `\\n` 或行尾 ⇒ **frontmatter 整个解析不出来**
    ⇒ 该页 `type` 为空 ⇒ 124 个页面在 `kb_lint` 里**静默失去全部元数据**
    （页面能正常打开、正文可读，人工浏览完全看不出）。
    这正是 CLAUDE.md 列为「危害高于任何一类」的失效形态。

    ⚠️ 我的前置校验也没拦住它：校验脚本用了 `re.match(r'^---\\r?\\n(.*?)\\r?\\n---')`
    ——**容忍「`---` 后无换行」**，比 kb_lib 的正则宽松，于是「校验通过、实际已坏」。
    ⇒ **校验必须用与被校验系统同一个解析器**（这里是 `kb_lib.split_frontmatter`），
      不要另写一个「差不多」的正则。

    本函数现在直接复用 `split_frontmatter`，并在写前断言能重新解析。
    """
    t = read_text(page_path)
    a, b = split_frontmatter(t)
    if not a:
        raise ValueError(f"无法解析 frontmatter，拒绝写入: {page_path}")
    if re.search(r"^evidence_base\s*:", a, re.M):
        a2 = re.sub(r"^evidence_base\s*:.*$", f"evidence_base: {value}", a,
                    count=1, flags=re.M)
    else:
        if re.search(r"^type\s*:", a, re.M):
            a2 = re.sub(r"^(type\s*:.*)$", r"\1" + f"\nevidence_base: {value}",
                        a, count=1, flags=re.M)
        else:
            a2 = a.rstrip("\n") + f"\nevidence_base: {value}"
    # 闭合 --- 后**必须**有换行，否则 frontmatter 解析不出来（124 页事故的形态）。
    # 🔴 走 kb_lib.join_frontmatter —— 本库的**唯一出口**。
    #    本文件此前手搓 `"---\n" + a2 + "\n---\n" + b`：虽然这次两个换行都在、结果正确，
    #    但同一写法在两个工具里各犯过一次（开围栏缺换行 / 闭合缺换行），
    #    而本文件正是那次事故的事后分析者——留着第 9 处手搓实现只会让它再犯。
    new = join_frontmatter(a2.strip("\n"), b)
    # 写前断言：用与 kb_lib 相同的解析器复核
    if not match_frontmatter(new):
        raise ValueError(f"写入后会破坏 frontmatter，已中止: {page_path}")
    if new != t:
        with open(page_path, "w", encoding="utf-8", newline="\n") as f:
            f.write(new)
        return True
    return False


def run_selftest():
    """夹具反算：正例与反例都要有（只测「该过的过了」会漏「该报的没报」）"""
    def fm(sr=None, si=None):
        d = {}
        if sr is not None:
            d["source_reliability"] = sr
        if si is not None:
            d["si_status"] = si
        return (d, "")

    peer = "同行评审（Nat. Commun. 13, 5454, 2022）"
    second = "二手（公众号解读，mp.weixin.qq.com）"
    pre = "预印本（arXiv:2401.00001，未经同行评审）"
    # ⚠️ 本库真实写法：**否认**自己不是预印本
    peer_denies_pre = "peer-reviewed-journal  # Adv. Mater. 正式发表（非预印本）"
    peer_en = "peer-reviewed（Nature Computational Science 5, 952-961, 2025）"
    peer_and_arxiv = "同行评审（Nat. Commun. 2022）；arXiv:2103.00001 为早期版本"

    cases = [
        # (描述, cited_fms, 期望)
        ("空 sources", [], "single-source"),
        ("单篇同行评审", [fm(peer)], "single-source"),
        ("两篇同行评审", [fm(peer), fm(peer)], "mixed"),
        ("五篇同行评审", [fm(peer)] * 5, "strong"),
        ("六篇但含 1 预印本", [fm(peer)] * 5 + [fm(pre)], "mixed"),
        ("六篇但含 1 二手", [fm(peer)] * 5 + [fm(second)], "mixed"),
        ("两篇二手 / 共三篇", [fm(peer), fm(second), fm(second)], "secondhand"),
        ("一篇二手 / 共两篇", [fm(peer), fm(second)], "secondhand"),
        ("三篇未标注", [fm(), fm(), fm()], "mixed"),
        ("十篇中仅 1 篇同行评审", [fm(peer)] + [fm()] * 9, "mixed"),
        ("九篇一手中含 2 同行评审", [fm(peer), fm(peer)] + [fm()] * 7, "strong"),
        # —— 回归夹具：判定顺序陷阱（首版曾使 127 页误判为预印本）——
        ("单篇：peer 且否认预印本", [fm(peer_denies_pre)], "single-source"),
        ("五篇：均为 peer 且否认预印本", [fm(peer_denies_pre)] * 5, "strong"),
        ("五篇英文 peer-reviewed", [fm(peer_en)] * 5, "strong"),
        ("五篇 peer 且提及 arXiv 早期版", [fm(peer_and_arxiv)] * 5, "strong"),
        # —— 反例：真预印本不得被当成 peer ——
        ("五篇真预印本", [fm(pre)] * 5, "mixed"),
        ("单篇真预印本", [fm(pre)], "single-source"),
        ("三篇真预印本", [fm(pre)] * 3, "mixed"),
    ]

    print("=== qc_evidence_base selftest ===")
    failed = 0
    for desc, cited, expect in cases:
        got, why = classify(cited)
        ok = got == expect
        if not ok:
            failed += 1
        mark = "PASS" if ok else "FAIL"
        print(f"  [{mark}] {desc:<26} expect={expect:<14} got={got:<14} | {why}")
    print()
    if failed:
        print(f"SELFTEST FAILED: {failed}/{len(cases)} wrong")
        return 1
    print(f"SELFTEST PASSED: {len(cases)}/{len(cases)} correct")
    return 0


def main():
    if "--help" in sys.argv or "-h" in sys.argv:
        print(__doc__ or "用法: python tools/qc_evidence_base.py [--apply] [--selftest]")
        return 0
    if "--selftest" in sys.argv:
        return run_selftest()
    apply = "--apply" in sys.argv
    src_pages = load_source_pages()
    print(f"已加载 source 页: {len(src_pages)}\n")

    dist = Counter()
    rows = []
    for d in ("concepts", "topics"):
        for f in sorted(glob.glob(f"wiki/{d}/*.md")):
            fm, hits = evidence_for(f, src_pages)
            name = os.path.basename(f)[:-3]
            n_srcs = len(fm.get("sources") or [])
            val, why = classify(hits)
            dist[val] += 1
            rows.append((d, name, n_srcs, len(hits), val, why))

    print("%-9s %-34s %6s %6s %-14s %s" %
          ("类型", "页面", "sources", "命中", "evidence_base", "依据"))
    for d, name, n_srcs, n_hit, val, why in rows:
        flag = "⚠️" if n_hit < n_srcs else "  "
        print("%-9s %-34s %6d %6d %-14s %s%s" %
              (d, name[:34], n_srcs, n_hit, val, flag, why))

    print("\n=== 取值分布 ===")
    for v in VALID:
        print("  %-14s %d" % (v, dist[v]))
    print("  合计          %d" % sum(dist.values()))

    unresolved = [r for r in rows if r[3] < r[2]]
    if unresolved:
        print(f"\n⚠️ {len(unresolved)} 页有 sources: 条目未解析到对应 source 页"
              f"（路径不匹配或页面不存在）——这些页的判定可能偏低：")
        for d, name, n_srcs, n_hit, val, _ in unresolved[:10]:
            print("   %s/%s  sources=%d 命中=%d" % (d, name, n_srcs, n_hit))

    if not apply:
        print("\n加 --apply 就地写入 evidence_base")
        return 0

    n = 0
    for d, name, _a, _b, val, _c in rows:
        if write_field(f"wiki/{d}/{name}.md", val):
            n += 1
    print(f"\n已写入 evidence_base: {n} 页")
    return 0


if __name__ == "__main__":
    sys.exit(main())
